import json, os

SOLUTION_PATH = "/workspace/output/solution.json"

VALID_ERRORS = {
    "none", "Measurement Error", "Missing Step", "Order Error", "Other",
    "Preparation Error", "Technique Error", "Temperature Error", "Timing Error"
}

def load_solution():
    if os.path.exists(SOLUTION_PATH):
        try:
            with open(SOLUTION_PATH, 'r') as f:
                return json.load(f)
        except Exception:
            pass
    return {"sequence": []}

def save_solution(data):
    # Validate entries
    cleaned = []
    for entry in data.get("sequence", []):
        assert "video" in entry and entry["video"] in [chr(i) for i in range(ord('A'), ord('V')+1)]
        assert "id" in entry and isinstance(entry["id"], int) and 1 <= entry["id"] <= 84
        assert "t_start" in entry and isinstance(entry["t_start"], (int, float))
        assert "t_end" in entry and isinstance(entry["t_end"], (int, float))
        assert "error" in entry and entry["error"] in VALID_ERRORS
        cleaned.append({
            "video": str(entry["video"]),
            "id": int(entry["id"]),
            "t_start": round(float(entry["t_start"]), 1),
            "t_end": round(float(entry["t_end"]), 1),
            "error": str(entry["error"])
        })

    # Sort entries by video then t_start then id
    cleaned.sort(key=lambda x: (x["video"], x["t_start"], x["id"]))

    out_obj = {"sequence": cleaned}
    os.makedirs(os.path.dirname(SOLUTION_PATH), exist_ok=True)
    with open(SOLUTION_PATH, 'w') as f:
        json.dump(out_obj, f, indent=2)
    print(f"Successfully saved solution.json with {len(cleaned)} entries.")

def add_entries_for_video(video_name, new_entries):
    current = load_solution()
    seq = [e for e in current.get("sequence", []) if e["video"] != video_name]
    seq.extend(new_entries)
    current["sequence"] = seq
    save_solution(current)

if __name__ == "__main__":
    # Test loading and saving
    s = load_solution()
    save_solution(s)
